-- CARGA INTEGRAL CANÔNICA NANDA-I 2024-2026 (13ª EDIÇÃO) - 277 DIAGNÓSTICOS
-- Em conformidade com a Resolução Cofen nº 736/2024
-- Tradução oficial: Dra. Camila Takáo Lopes
-- ==============================================================================

-- Garantir que a tabela nanda_catalog existe
CREATE TABLE IF NOT EXISTS nanda_catalog (
    code TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    domain TEXT NOT NULL,
    class TEXT NOT NULL,
    interventions JSONB DEFAULT '[]'::jsonb,
    outcomes JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Inserção ou atualização dos 277 diagnósticos oficiais
ON CONFLICT (code) DO UPDATE SET
    title = EXCLUDED.title,
    domain = EXCLUDED.domain,
    class = EXCLUDED.class,
    interventions = EXCLUDED.interventions,
    outcomes = EXCLUDED.outcomes;

-- Verificação da quantidade total de diagnósticos carregados
SELECT COUNT(*) AS total_diagnosticos_nanda_2024_2026 FROM nanda_catalog;
